// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/health", wrapper.GetHealth)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/me", wrapper.DeactivateMe)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/me", wrapper.ProvisionMe)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/me/reactivate", wrapper.ReactivateMe)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/entries", wrapper.ListEntries)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/entries", wrapper.CreateEntry)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/entries/{id}", wrapper.DeleteEntry)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/entries/{id}", wrapper.UpdateEntry)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/categories/{id}", wrapper.DeleteCategory)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/categories/{id}", wrapper.UpdateCategory)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/days/{date}/order", wrapper.ReorderDay)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/categories", wrapper.CreateCategory)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/entries/{id}/photos/presign", wrapper.PresignPhotos)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/entries/{id}/photos", wrapper.RegisterPhotos)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/entries/{id}/photos/order", wrapper.ReorderPhotos)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/photos/{id}", wrapper.DeletePhoto)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/months/{month}", wrapper.GetMonth)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/years/{year}", wrapper.GetYear)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/color-recents", wrapper.ListColorRecents)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/color-recents", wrapper.SaveColorRecent)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/color-recents/{hex}", wrapper.ForgetColorRecent)
	})

	return r
}

