// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// CreateCategory Create a Category or Subcategory
	// (POST /categories)
	CreateCategory(ctx context.Context, request CreateCategoryRequestObject) (CreateCategoryResponseObject, error)
	// DeleteCategory Delete an unused Category
	// (DELETE /categories/{id})
	DeleteCategory(ctx context.Context, request DeleteCategoryRequestObject) (DeleteCategoryResponseObject, error)
	// UpdateCategory Rename or restyle a Category
	// (PATCH /categories/{id})
	UpdateCategory(ctx context.Context, request UpdateCategoryRequestObject) (UpdateCategoryResponseObject, error)
	// ListColorRecents The signed-in User's saved custom colors
	// (GET /color-recents)
	ListColorRecents(ctx context.Context, request ListColorRecentsRequestObject) (ListColorRecentsResponseObject, error)
	// SaveColorRecent Save a custom color as most recently used
	// (PUT /color-recents)
	SaveColorRecent(ctx context.Context, request SaveColorRecentRequestObject) (SaveColorRecentResponseObject, error)
	// ForgetColorRecent Forget a saved custom color
	// (DELETE /color-recents/{hex})
	ForgetColorRecent(ctx context.Context, request ForgetColorRecentRequestObject) (ForgetColorRecentResponseObject, error)
	// ReorderDay Reorder a date's Entries
	// (PUT /days/{date}/order)
	ReorderDay(ctx context.Context, request ReorderDayRequestObject) (ReorderDayResponseObject, error)
	// ListEntries List a date's Entries in order
	// (GET /entries)
	ListEntries(ctx context.Context, request ListEntriesRequestObject) (ListEntriesResponseObject, error)
	// CreateEntry Create an Entry
	// (POST /entries)
	CreateEntry(ctx context.Context, request CreateEntryRequestObject) (CreateEntryResponseObject, error)
	// DeleteEntry Delete an Entry
	// (DELETE /entries/{id})
	DeleteEntry(ctx context.Context, request DeleteEntryRequestObject) (DeleteEntryResponseObject, error)
	// UpdateEntry Update an Entry
	// (PATCH /entries/{id})
	UpdateEntry(ctx context.Context, request UpdateEntryRequestObject) (UpdateEntryResponseObject, error)
	// RegisterPhotos Record uploaded photos on an Entry
	// (POST /entries/{id}/photos)
	RegisterPhotos(ctx context.Context, request RegisterPhotosRequestObject) (RegisterPhotosResponseObject, error)
	// ReorderPhotos Reorder an Entry's photos
	// (PUT /entries/{id}/photos/order)
	ReorderPhotos(ctx context.Context, request ReorderPhotosRequestObject) (ReorderPhotosResponseObject, error)
	// PresignPhotos Presign direct-to-storage uploads for an Entry's photos
	// (POST /entries/{id}/photos/presign)
	PresignPhotos(ctx context.Context, request PresignPhotosRequestObject) (PresignPhotosResponseObject, error)
	// GetHealth Liveness and database health
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// DeactivateMe Deactivate the signed-in User's account
	// (DELETE /me)
	DeactivateMe(ctx context.Context, request DeactivateMeRequestObject) (DeactivateMeResponseObject, error)
	// ProvisionMe Provision and return the signed-in User's world
	// (POST /me)
	ProvisionMe(ctx context.Context, request ProvisionMeRequestObject) (ProvisionMeResponseObject, error)
	// ReactivateMe Restore a deactivated account within its grace period
	// (POST /me/reactivate)
	ReactivateMe(ctx context.Context, request ReactivateMeRequestObject) (ReactivateMeResponseObject, error)
	// GetMonth A month's dot structure in one call
	// (GET /months/{month})
	GetMonth(ctx context.Context, request GetMonthRequestObject) (GetMonthResponseObject, error)
	// DeletePhoto Delete a photo
	// (DELETE /photos/{id})
	DeletePhoto(ctx context.Context, request DeletePhotoRequestObject) (DeletePhotoResponseObject, error)
	// GetYear A year's day colors in one call
	// (GET /years/{year})
	GetYear(ctx context.Context, request GetYearRequestObject) (GetYearResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

